import { after } from 'next/server'
import { headers } from 'next/headers'
import { logPageView } from './lib/analytics'

export default async function Home() {
  // Request APIs must be read during render — calling headers() inside the
  // after() callback throws in Server Components.
  const userAgent = (await headers()).get('user-agent') || 'unknown'

  after(() => {
    // Runs after the response is sent, so it never blocks the page.
    logPageView({
      path: '/',
      userAgent,
      timestamp: new Date().toISOString(),
    })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>We&apos;re glad you&apos;re here.</p>
    </main>
  )
}

